#include "tgcloud/backup/backup.hpp"
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <random>
#include <stdexcept>
namespace tgcloud::backup {static void key(std::string_view pw,const unsigned char*s,unsigned char*k){std::string x(pw);x.append((char*)s,16);SHA256((unsigned char*)x.data(),x.size(),k);}std::string encrypt(std::string_view in,std::string_view pw){unsigned char s[16],iv[16],k[32];std::random_device r;for(auto&x:s)x=r();for(auto&x:iv)x=r();key(pw,s,k);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();EVP_EncryptInit_ex(c,EVP_aes_256_cbc(),nullptr,k,iv);std::string e(in.size()+16,0);int n=0,z=0;EVP_EncryptUpdate(c,(unsigned char*)e.data(),&n,(unsigned char*)in.data(),in.size());EVP_EncryptFinal_ex(c,(unsigned char*)e.data()+n,&z);EVP_CIPHER_CTX_free(c);std::string o="BKP1";o.append((char*)s,16);o.append((char*)iv,16);o.append(e.data(),n+z);return o;}std::string decrypt(std::string_view b,std::string_view pw){if(b.size()<36||b.substr(0,4)!="BKP1")throw std::runtime_error("invalid backup");unsigned char k[32];key(pw,(unsigned char*)b.data()+4,k);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();EVP_DecryptInit_ex(c,EVP_aes_256_cbc(),nullptr,k,(unsigned char*)b.data()+20);std::string p(b.size()-36,0);int n=0,z=0;EVP_DecryptUpdate(c,(unsigned char*)p.data(),&n,(unsigned char*)b.data()+36,b.size()-36);if(EVP_DecryptFinal_ex(c,(unsigned char*)p.data()+n,&z)<=0){EVP_CIPHER_CTX_free(c);throw std::runtime_error("backup decryption failed");}EVP_CIPHER_CTX_free(c);p.resize(n+z);return p;}}
